{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_827625fc9e3b855d60f1a9f0", "claim_ids": ["claim_d119bc054e534700289d9dc8", "claim_f121c6ae83cb279d26a53bd6"], "query_ids": ["q_235"], "claims": [{"claim_id": "claim_d119bc054e534700289d9dc8", "quote": "Tariffs take effect this week, creating pricing instability across the auto industry.", "url": "https://www.facebook.com/quartznews/posts/hyundai-is-weighing-a-massive-expansion-of-its-georgia-car-plant-citing-tariffs-/1419057173423430", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Tariffs", "effective_date": "this week"}}, {"claim_id": "claim_f121c6ae83cb279d26a53bd6", "quote": "The 15% tariff applied to South Korean imports is increasing the economic incentive for local production expansion.", "url": "https://finance.biggo.com/news/7c816f70-187d-4f54-84d6-c8c8f26bacb6", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "15%"}}]}, {"pair_id": "conflict_f859327e3bbffd4df395d307", "claim_ids": ["claim_91e310682eb7020e1489d176", "claim_9312f7b923c808a1a6a60acb"], "query_ids": ["q_236"], "claims": [{"claim_id": "claim_91e310682eb7020e1489d176", "quote": "To avoid U.S. tariffs, automakers like Tesla and Hyundai are moving battery and component manufacturing to Vietnam, Malaysia, and Mexico.", "url": "https://blogs.tradlinx.com/shifting-gears-how-tariffs-and-trade-wars-are-rewiring-the-automotive-supply-chain", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Tesla"}}, {"claim_id": "claim_9312f7b923c808a1a6a60acb", "quote": "To avoid U.S. tariffs, automakers like Tesla and Hyundai are moving battery and component manufacturing to Vietnam, Malaysia, and Mexico.", "url": "https://blogs.tradlinx.com/shifting-gears-how-tariffs-and-trade-wars-are-rewiring-the-automotive-supply-chain", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}, {"pair_id": "conflict_bcf85b67eafad54fed67ef62", "claim_ids": ["claim_6ca3cfd95d9ca149f551f677", "claim_b3e64e31e04f93c56b117540"], "query_ids": ["q_236"], "claims": [{"claim_id": "claim_6ca3cfd95d9ca149f551f677", "quote": "President Joe Biden on Tuesday raised tariffs in an effort to protect American electric vehicle and solar panel industries from cheap Chinese imports, ramping up an ongoing trade war between the two global superpowers that could impact Georgia’s burgeoning clean tech sector.", "url": "https://www.ajc.com/news/business/how-will-new-chinese-tariffs-affect-georgia-business-its-complicated/7XZZOOZMUVH6TPWP2ZJY74GIFQ", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "raised tariffs", "affected_product": "electric vehicle and solar panel industries"}}, {"claim_id": "claim_b3e64e31e04f93c56b117540", "quote": "The Democratic president quadrupled tariffs on Chinese EVs and sharply increased import taxes on solar panels and raw materials like semiconductors that are used to produce plug-in cars.", "url": "https://www.ajc.com/news/business/how-will-new-chinese-tariffs-affect-georgia-business-its-complicated/7XZZOOZMUVH6TPWP2ZJY74GIFQ", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "quadrupled tariffs", "affected_product": "Chinese EVs"}}]}, {"pair_id": "conflict_e9f6a34bfb55bfa6a547d81b", "claim_ids": ["claim_3bb5982d357506707d154214", "claim_7ca957ed2a8d8c86c801dd0e"], "query_ids": ["q_238"], "claims": [{"claim_id": "claim_3bb5982d357506707d154214", "quote": "Presently, most batteries and critical battery materials are produced in China, but American technological innovation and industrial policy have put the nation in a strategic position to lead the next generation of battery development.", "url": "https://www.c2es.org/document/securing-the-critical-battery-materials-supply-chain-in-the-southeast-united-states", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"country_of_origin": "China", "exporting_country": "China"}}, {"claim_id": "claim_7ca957ed2a8d8c86c801dd0e", "quote": "The top two global battery suppliers are Chinese, with China having produced more than 70 percent of all EV batteries ever manufactured.", "url": "https://www.c2es.org/document/securing-the-critical-battery-materials-supply-chain-in-the-southeast-united-states", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"country_of_origin": "China", "exporting_country": "China"}}]}, {"pair_id": "conflict_6957538c5a7fcd195958ffd0", "claim_ids": ["claim_907ba6bf60e5e5986042718f", "claim_9af3e5b325880203e1bdd631"], "query_ids": ["q_238"], "claims": [{"claim_id": "claim_907ba6bf60e5e5986042718f", "quote": "New requirements include that the cars must be assembled in North America and that materials and critical minerals in the battery must come from the U.S. or a country with a free trade agreement with the U.S.", "url": "https://www.coxautoinc.com/mobility/wp-content/uploads/sites/11/2022/09/EV_Battery_Whitepaper.pdf", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_9af3e5b325880203e1bdd631", "quote": "China controls nearly three-quarters of the market for the raw materials that go into these batteries.", "url": "https://www.coxautoinc.com/mobility/wp-content/uploads/sites/11/2022/09/EV_Battery_Whitepaper.pdf", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"exporting_country": "China"}}]}, {"pair_id": "conflict_3af51f330c4d4854504671ee", "claim_ids": ["claim_5bb5d449626fbc4790742ef5", "claim_aeec262d58c34f96687a4bd4"], "query_ids": ["q_240"], "claims": [{"claim_id": "claim_5bb5d449626fbc4790742ef5", "quote": "the expected October 15 end of the tariff truce between the US and China that temporarily brough