      "requires_current_authority_verification": false
    },
    "conflict_bcf85b67eafad54fed67ef62": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 1 states tariffs were 'raised' on EVs and solar panels, while Claim 2 specifies the action as 'quadrupled' on Chinese EVs and increased taxes on solar panels. These are consistent descriptions of the same policy action with varying levels of detail.",
      "requires_current_authority_verification": false
    },
    "conflict_e9f6a34bfb55bfa6a547d81b": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 1 notes most batteries are produced in China, and Claim 2 states Chinese suppliers produce over 70% of all EV batteries. Both claims align on the dominance of China in battery production without contradiction.",
      "requires_current_authority_verification": false
    },
    "conflict_6957538c5a7fcd195958ffd0": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 1 outlines requirements for U.S. or FTA country origins, while Claim 2 notes China controls the raw materials market. These are complementary facts regarding supply chain constraints and regulatory requirements, not conflicting claims.",
      "requires_current_authority_verification": false
    },
    "conflict_3af51f330c4d4854504671ee": {
      "classification": "different_dates_or_policy_stages",
      "reason": "Claim 1 refers to an 'October 15' expiration of a truce, while Claim 2 refers to a 'mid-October' expiration. These represent the same policy stage (expiration) with slightly different date descriptors, not a conflict.",
      "requires_current_authority_verification": false
    },
    "conflict_1c6be60b9f5d777d1910f6fd": {
      "classification": "different_dates_or_policy_stages",
      "reason": "Claim 1 reports a 7.5% decline in GPA volume for 2025, while Claim 2 reports a 14.3% fall in shipments and an 11.8% fiscal year decline as of October 2025. The differing metrics (volume vs. shipment value/percentage) and timeframes indicate different reporting stages rather than a direct conflict.",
      "requires_current_authority_verification": false
    },
    "conflict_48668629a4f9200e3d8ef700": {
      "classification": "different_products_origins_or_programs",
      "reason": "Claim 1 cites Proclamation 10908 effective April 3, 2025, for automobiles and parts. Claim 2 cites Section 232 guidance effective May 3, 2025, specifically for automobile parts. The different effective dates and specific product scopes (autos vs. parts) indicate distinct policy stages.",
      "requires_current_authority_verification": false
    },
    "conflict_c080e372e564bb0b6c33dd96": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 1 states auto parts are exempt from reciprocal duties under Section 232, and Claim 2 confirms that the specific HTS heading exempts these products. Both claims describe the same exemption mechanism consistently.",
      "requires_current_authority_verification": false
    },
    "conflict_e185222be00af5f917943fa5": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 1 lists commercial vehicles subject to Section 232 duties, and Claim 2 details that parts for these same vehicle types are also covered under Section 232 measures. The claims describe the scope of coverage for vehicles and their parts consistently.",
      "requires_current_authority_verification": false
    }
  }
}
